// ── Language metadata ────────────────────────────────────────────────────────

export const LANGUAGES: { value: Lang; label: string; flag: string; native: string }[] = [
  { value: 'en', label: 'English',    flag: '🇬🇧', native: 'English'    },
  { value: 'de', label: 'German',     flag: '🇩🇪', native: 'Deutsch'    },
  { value: 'fr', label: 'French',     flag: '🇫🇷', native: 'Français'   },
  { value: 'es', label: 'Spanish',    flag: '🇪🇸', native: 'Español'    },
  { value: 'nl', label: 'Dutch',      flag: '🇳🇱', native: 'Nederlands' },
  { value: 'zh', label: 'Chinese',    flag: '🇨🇳', native: '中文'       },
]

export const LANG_LABELS: Record<string, string> = Object.fromEntries(
  LANGUAGES.map(l => [l.value, l.native])
)

export const SEARCH_TARGET_LANGS: { value: string; label: string }[] = [
  { value: 'en', label: 'English'  },
  { value: 'de', label: 'Deutsch'  },
  { value: 'fr', label: 'Français' },
  { value: 'es', label: 'Español'  },
  { value: 'nl', label: 'Nederlands'},
  { value: 'zh', label: '中文'     },
  { value: 'ja', label: 'Japanese'   },
]

export function translate(lang: Lang, key: string): string {
  if (dict[lang]?.[key]) return dict[lang][key]
  if (lang === 'zh') return dict.zh['common.somethingWentWrong'] ?? '出现了问题'
  return dict.en?.[key] ?? key
}

export const TRANSLATION_KEYS = Object.keys(dict.en)

export function hasTranslation(lang: Lang, key: string): boolean {
  return Boolean(dict[lang]?.[key])
}

// ── Context ──────────────────────────────────────────────────────────────────

interface I18nContextValue {
  lang: Lang
  t:    (key: string) => string
  setLang: (l: Lang) => void
}

const I18nContext = createContext<I18nContextValue>({
  lang: 'en',
  t:    (key) => translate('en', key),
  setLang: () => {},
})

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('applymate_lang')
      return LANGUAGES.some(language => language.value === stored) ? stored as Lang : 'en'
    }
    return 'en'
  })

  const setLang = useCallback((l: Lang) => {
    setLangState(l)
    if (typeof document !== 'undefined') document.documentElement.lang = l
    try { localStorage.setItem('applymate_lang', l) } catch {}
  }, [])

  const t = useCallback((key: string): string => {
    return translate(lang, key)
  }, [lang])

  React.useEffect(() => {
    document.documentElement.lang = lang
  }, [lang])

  const value = useMemo(() => ({ lang, t, setLang }), [lang, t, setLang])
  return React.createElement(I18nContext.Provider, { value }, children)
}

export function useI18n() {
  return useContext(I18nContext)
}

